package io.forgeloop.control.application;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*; import io.forgeloop.control.domain.*; import java.util.*; import org.junit.jupiter.api.Test;
class TaskLeaseServiceTest { DeliveryTaskRepository tasks=mock(DeliveryTaskRepository.class); RunnerRepository runners=mock(RunnerRepository.class); TaskLeaseRepository leases=mock(TaskLeaseRepository.class); VerificationEvidenceRepository evidence=mock(VerificationEvidenceRepository.class); TaskLeaseService service=new TaskLeaseService(tasks,runners,leases,evidence); @Test void claimCreatesExpiringSingleOwnerLease(){FeatureRun run=new FeatureRun("a/b","issue-1","x","- x",1,"GENERIC",1);run.addTask("IMPLEMENTATION","x","git");DeliveryTask task=run.getTasks().getFirst();Runner runner=new Runner("org","node","1",List.of("git"),"credential-hash");when(tasks.findById("task")).thenReturn(Optional.of(task));when(runners.findById("runner")).thenReturn(Optional.of(runner));when(leases.findByTask_Id("task")).thenReturn(Optional.empty());when(leases.save(any())).thenAnswer(call->call.getArgument(0));LeaseGrant grant=service.claim("task","runner");assertEquals(64,grant.nonce().length());assertEquals(TaskState.LEASED,task.getState());} }
